Definition wnd : Type := (saddr * Z)%type.
Definition kdj (w w' : wnd) : kentry := KDisj (fst w) (ELit (snd w)) (fst w') (ELit (snd w')).
Fixpoint kdisj_pairs (ws : list wnd) : list kentry :=
  match ws with [] => [] | w :: r => map (kdj w) r ++ kdisj_pairs r end.
Definition kdisj_vs (c : wnd) (ws : list wnd) : list kentry := map (kdj c) ws.
Definition kwrs (ws : list wnd) : list kentry := map (fun w => KWr (fst w) (ELit (snd w))) ws.

Definition shb (v : N) (k : Z) : expr :=
  if Z.eqb k 0 then EAlu ALU_SRL (EVar v) (ELit 3) else EAlu ALU_SRL (EAlu ALU_ADD (EVar v) (ELit k)) (ELit 3).
Definition shw (vk : N * Z) : wnd := (SA (shb (fst vk) (snd vk)) SHBASE, 1).

Definition kshp (ws : list wnd) (vk : N * Z) : list kentry := KWord (SA (shb (fst vk) (snd vk)) SHBASE) 1 (ELit 0) :: kdisj_vs (shw vk) ws.
Definition kshps (ws : list wnd) (vks : list (N * Z)) : list kentry := flat_map (kshp ws) vks.

