Section Bundles.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Variables (sp : word) (ds p n fl lo ff1 fp1 spa : Z).
  Notation spz := (bv_unsigned sp) (only parsing).

  Record qg1 : Prop := QG1 {
    g_lo : aceil <= lo /\ lo <= spz - ADS_STACK;
    g_sp : spz mod 16 = 0 /\ spz <= AAPP_HI;
    g_spa : spa mod 32 = 0 /\ spz - 208 <= spa <= spz - 192;
    g_ds : app_obj ds DS_SIZE /\ ds mod 8 = 0 /\ ds + DS_SIZE + 64 <= AAPP_HI /\ ds + DS_SIZE <= aceil;
    g_dsfs : as_FSB H <= ds /\ ds + DS_SIZE <= as_FSB H + AFS_SIZE;
    g_pn : 0 <= p /\ p + n <= 2 ^ 47 /\ 0 <= n <= DS_MAXLEN;
    g_fl : fl = DS_FL0 \/ fl = DS_FLHEX;
    g_f1 : aframe_range H 1 ff1 fp1 /\ afsb_ok H;
    g_f1ds : (ff1 + 128 <= ds \/ ds + DS_SIZE <= ff1) /\ (fp1 + 1 <= ds \/ ds + DS_SIZE <= fp1)
             /\ (hull_hi (ds + DS_SIZE) <= ff1 \/ ff1 + 128 <= hull_lo ds)
  }.

  Record dsf (m : mem) : Prop := DSF {
    f_vt : rw_cells asegs m ds [C8 (Z_to_bv 64 VT_OS_A)];
    f_sbvt : rw_cells asegs m (ds + 8) [C8 (Z_to_bv 64 VT_SB_A)];
    f_iosvt : rw_cells asegs m (ds + 112) [C8 (Z_to_bv 64 VT_IOS_A)];
    f_flags : rw_cells asegs m (ds + 120) [C4 (Z_to_bv 64 fl)];
    f_state : rw_cells asegs m (ds + 144) [C4 (Z_to_bv 64 0)];
    f_rdbuf : rw_cells asegs m (ds + 152) [C8 (Z_to_bv 64 (ds + 8))];
    f_loc : rw_cells asegs m (ds + 160) [C8 (Z_to_bv 64 LOC_IMP_A)];
    f_tie : rw_cells asegs m (ds + 248) [C8 (Z_to_bv 64 0)]
  }.
  Record qf1 (m : mem) : Prop := QF1 {
    q_ac : ACONST m;
    q_lv : LINV_P5 m;
    q_stk : stk asegs m lo spz;
    q_dsa : addressable m ds DS_SIZE;
    q_dsw : wr_at asegs m ds DS_SIZE;
    q_dsv : shvis m ds (ds + DS_SIZE);
    q_dsf : dsf m;
    q_f1w : wr_at asegs m ff1 128;
    q_h1w : wr_at asegs m (sh ff1) 16;
    q_l1w : wr_at asegs m fp1 1
  }.

  Variables (ff2 fp2 : Z).
  Record qg2 : Prop := QG2 {
    g_f2 : aframe_range H 1 ff2 fp2;
    g_f2ds : (ff2 + 128 <= ds \/ ds + DS_SIZE <= ff2) /\ (fp2 + 1 <= ds \/ ds + DS_SIZE <= fp2)
             /\ (hull_hi (ds + DS_SIZE) <= ff2 \/ ff2 + 128 <= hull_lo ds);
    g_f12 : (ff1 + 128 <= ff2 \/ ff2 + 128 <= ff1) /\ (fp1 + 1 <= fp2 \/ fp2 + 1 <= fp1)
  }.
  Record qx2 (m : mem) : Prop := QX2 {
    q_f2w : wr_at asegs m ff2 128;
    q_h2w : wr_at asegs m (sh ff2) 16;
    q_l2w : wr_at asegs m fp2 1
  }.
End Bundles.

Section Q.
