     Z_to_bv 64 ff1; Z_to_bv 64 fp1; Z_to_bv 64 fl; Z_to_bv 64 spa].

  Lemma q1_ranges :
    0 <= spz < 2 ^ 64 /\ aceil + ADS_STACK <= spz /\ spz <= AAPP_HI /\ spz mod 16 = 0
    /\ spa mod 32 = 0 /\ spz - 208 <= spa <= spz - 192
    /\ as_FSB H + AFS_HDR <= ff1 /\ ff1 + 128 <= as_FSB H + AFS_SIZE /\ ff1 mod 64 = 0
    /\ as_FSB H + AFS_FLAGS <= fp1 < as_FSB H + AFS_HDR
    /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil
    /\ (as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H)
    /\ 0x7fff7f800000 <= aceil <= 0x7fffff800000
    /\ AIMG_TOP <= ds /\ (ds + DS_SIZE <= ALOWSH_LO \/ AHI_LO <= ds) /\ ds + DS_SIZE + 64 <= AAPP_HI /\ ds + DS_SIZE <= aceil /\ ds mod 8 = 0
    /\ 0 <= p /\ p + n <= 2 ^ 47 /\ 0 <= n <= DS_MAXLEN /\ (fl = DS_FL0 \/ fl = DS_FLHEX)
    /\ aceil <= lo /\ lo <= spz - ADS_STACK.
